    <h2>Cover Letter</h2>

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea class="form-control cover-letter-textarea" rows="12" maxlength="@MaxLength" @bind="CoverLetter" @bind:event="oninput" @bind:after="NotifyChanged" placeholder="Tell us why you're a great fit for this role..."></textarea>
        <span class="char-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </span>
    </div>

    @if (!string.IsNullOrEmpty(_error))
    {
        <p class="field-error">@_error</p>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _error;

    private async Task NotifyChanged()
    {
        await CoverLetterChanged.InvokeAsync(CoverLetter);
    }

    private async Task HandleNext()
    {
        _error = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            _error = "Please write a cover letter.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

